export interface AgentPromptRow {
  /** basename of the .claude/agents/<id>.md file, used as DOM key. */
  agentId: string;
  /** Human-readable role label from the generator's ROLE_MAP. */
  role: string;
  /** Repo-relative path to the committed prompt file (plain text, not a link). */
  filePath: string;
  /** First 2000 characters of the file body (frontmatter stripped). */
  excerpt: string;
  /** Full character count of the on-disk file (so a truncation is auditable). */
  fullCharCount: number;
  /** Short SHA of the commit that last modified the file. */
  lastModifiedSha: string;
}

export const PAGE_H1: string = "Agent Prompts";
export const PAGE_URL: string = "https://digitalcraftai.com/agent-prompts";
export const COLLECTION_PAGE_NAME: string = "Digital Craft AI Agent Prompts";

export const AGENT_PROMPTS_GENERATED_AT: string = "2026-10-02";

export const AGENT_PROMPTS_BUILD_SHA: string = "2ead458";

export const AGENT_PROMPTS_CAVEAT: string = "The excerpt below for each autonomous agent is the first 2000 characters of the committed prompt file at the build SHA, verified byte-identical to the version-controlled .claude/agents/<agentId>.md source by the build-time generator. The agents may receive additional runtime context from the fleet runner (environment, branch head SHA, prior PR state, autonomous ship-loop configuration) that is NOT in the committed prompt file; that runtime context is a distinct observability surface documented on /how-we-ship and /agent-fleet.";

/**
 * GitHub blob URL template. The {sha} placeholder is replaced at build
 * time with the git short SHA; {agentId} is the per-row basename. The
 * owner/repo pair is pinned to the public source-of-truth repository
 * so a reader can click through to the full prompt body at a stable
 * dated reference.
 */
export const AGENT_PROMPTS_GITHUB_URL_TEMPLATE: string = "https://github.com/mutaaf/digital-craft-architect/blob/{sha}/.claude/agents/{agentId}.md";

/**
 * Resolve a per-row "View full prompt" href by substituting the build
 * SHA and the row's agentId into the template.
 */
export function resolveAgentPromptGithubUrl(agentId: string): string {
  return AGENT_PROMPTS_GITHUB_URL_TEMPLATE.replace(
    "{sha}",
    AGENT_PROMPTS_BUILD_SHA,
  ).replace("{agentId}", agentId);
}

